{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C28"],
      "claim": "Praziquantel, the highest-transfer analogue, has an absolute oral bioavailability of 27.2±5.4% even in patients with hepatic impairment, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Pethidine, an ester-containing tertiary amine with high transferability, has an absolute oral bioavailability of 0.52 in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Solifenacin, with high transferability, shows an absolute oral bioavailability of 88% in healthy volunteers, strongly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Encainide, with high transferability, has an oral bioavailability of 20-30% in healthy subjects, still at or above the F ≥ 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Benazepril, an ester prodrug with high transferability, has an oral bioavailability of 28-37% in healthy volunteers, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues report absolute oral bioavailability at or above 20%, mostly 30-90%, with no contradictory evidence. The query's favorable physicochemical properties and structural alignment with ester/amine drugs showing high F support a high prediction.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query molecule itself is provided; the decision relies on high-transfer analogues.",
    "Potential first-pass ester hydrolysis and thiophene metabolism of the query are not directly quantified, though ester-containing analogues still exceed 20%.",
    "Some analogue data were obtained in patients with hepatic disease, which may not reflect healthy-subject bioavailability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

